import { describe, expect, it } from 'vitest';

import { concat, fromHex, repeatTo, toHex, utf16beWithNullTerminator } from './bytes';

describe('toHex / fromHex', () => {
  it('round-trips arbitrary bytes', () => {
    const bytes = new Uint8Array([0x00, 0x55, 0x50, 0x4d, 0xff]);
    expect(toHex(bytes)).toBe('0055504dff');
    expect(Array.from(fromHex('0055504dff'))).toEqual(Array.from(bytes));
  });

  it('ignores whitespace and colons', () => {
    expect(Array.from(fromHex('00 55:50'))).toEqual([0x00, 0x55, 0x50]);
  });

  it('rejects odd-length hex', () => {
    expect(() => fromHex('abc')).toThrow();
  });
});

describe('concat', () => {
  it('joins arrays in order', () => {
    const joined = concat(new Uint8Array([1, 2]), new Uint8Array([]), new Uint8Array([3]));
    expect(Array.from(joined)).toEqual([1, 2, 3]);
  });
});

describe('repeatTo', () => {
  it('repeats and truncates to the requested length', () => {
    expect(Array.from(repeatTo(new Uint8Array([0xaa, 0xbb]), 5))).toEqual([
      0xaa, 0xbb, 0xaa, 0xbb, 0xaa,
    ]);
  });

  it('rejects an empty source array', () => {
    expect(() => repeatTo(new Uint8Array([]), 4)).toThrow();
  });
});

describe('utf16beWithNullTerminator', () => {
  it('matches the BouncyCastle encoding from doc/crypto.md', () => {
    expect(toHex(utf16beWithNullTerminator('test123'))).toBe(
      '00740065007300740031003200330000',
    );
  });

  it('has length (characters + 1) * 2', () => {
    expect(utf16beWithNullTerminator('').length).toBe(2);
    expect(utf16beWithNullTerminator('ab').length).toBe(6);
  });
});
